-- GenDB engine variant Q16-commuted_comparisons: template q16.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  p_brand,
  p_type,
  p_size,
  COUNT(DISTINCT ps_suppkey) AS supplier_cnt
FROM partsupp, part
WHERE
  ps_partkey = p_partkey
  AND $1 <> p_brand
  AND NOT p_type LIKE $2
  AND p_size IN ($3, $4, $5, $6, $7, $8, $9, $10)
  AND NOT ps_suppkey IN (
    SELECT
      s_suppkey
    FROM supplier
    WHERE
      s_comment LIKE '%Customer%Complaints%'
  )
GROUP BY
  p_brand,
  p_type,
  p_size
ORDER BY
  supplier_cnt DESC,
  p_brand,
  p_type,
  p_size
